public class ContactTriggerHandler {

    public static void run() {
        if (Trigger.isBefore) {
            handleBefore();
        }
        if (Trigger.isAfter && Trigger.isInsert) {
            handleAfterInsert();
        }
    }

    /**
     * Before insert/update: populate the contact's MailingCountry (and LeadSource on
     * insert) from its parent account when the contact value is blank. Uses a single
     * bulk SOQL query.
     */
    private static void handleBefore() {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : Trigger.new) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }
        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accountsById = new Map<Id, Account>(
            [SELECT Id, BillingCountry, AccountSource FROM Account WHERE Id IN :accountIds]
        );

        Boolean isInsert = Trigger.isInsert;
        for (Contact c : Trigger.new) {
            if (c.AccountId == null) {
                continue;
            }
            Account a = accountsById.get(c.AccountId);
            if (a == null) {
                continue;
            }
            if (String.isBlank(c.MailingCountry)) {
                c.MailingCountry = a.BillingCountry;
            }
            if (isInsert && String.isBlank(c.LeadSource)) {
                c.LeadSource = a.AccountSource;
            }
        }
    }

    /**
     * After insert: for every account that still has no phone, copy the phone from the
     * first contact (in trigger order) of that account that has one. All updates are
     * performed with a single bulk DML statement.
     */
    private static void handleAfterInsert() {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : Trigger.new) {
            if (c.AccountId != null && String.isNotBlank(c.Phone)) {
                accountIds.add(c.AccountId);
            }
        }
        if (accountIds.isEmpty()) {
            return;
        }

        List<Account> accounts = [SELECT Id, Phone FROM Account WHERE Id IN :accountIds];

        List<Account> accountsToUpdate = new List<Account>();
        for (Account a : accounts) {
            if (String.isNotBlank(a.Phone)) {
                continue;
            }
            String phone = firstPhoneForAccount(a.Id);
            if (phone != null) {
                a.Phone = phone;
                accountsToUpdate.add(a);
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }

    // Returns the phone of the first contact (in trigger order) for the given account,
    // or null if none has one — preserving the original "first contact wins" behaviour.
    private static String firstPhoneForAccount(Id accountId) {
        for (Contact c : Trigger.new) {
            if (c.AccountId == accountId && String.isNotBlank(c.Phone)) {
                return c.Phone;
            }
        }
        return null;
    }
}
