public class PaymentTerms {
    private static final Pattern NET_PATTERN = Pattern.compile('^NET\\s*(\\d{1,3})$');
    private static final Pattern DUE_ON_RECEIPT_PATTERN = Pattern.compile('^DUE\\s+ON\\s+RECEIPT$');

    /**
     * Parses free-text payment terms and returns the number of net days.
     *
     * @param terms the raw payment terms string (e.g. "NET 30", "net30", "DUE ON RECEIPT")
     * @return the number of net days (0 for "DUE ON RECEIPT")
     * @throws UnsupportedTermsException if the terms are null, blank or unrecognized
     * @throws TermsOutOfRangeException if the net days exceed 180
     */
    public static Integer parseNetDays(String terms) {
        if (terms == null) {
            throw new UnsupportedTermsException('Unsupported payment terms: null');
        }

        String normalized = terms.trim().toUpperCase();

        Matcher netMatcher = NET_PATTERN.matcher(normalized);
        if (netMatcher.matches()) {
            Integer days = Integer.valueOf(netMatcher.group(1));
            if (days > 180) {
                throw new TermsOutOfRangeException('Net days out of range: ' + days);
            }
            return days;
        }

        if (DUE_ON_RECEIPT_PATTERN.matcher(normalized).matches()) {
            return 0;
        }

        throw new UnsupportedTermsException('Unsupported payment terms: ' + terms);
    }

    /**
     * Computes the invoice due date from the invoice date and payment terms.
     *
     * @param invoiceDate the date the invoice was issued
     * @param terms the raw payment terms string
     * @return the due date (invoice date plus net days)
     * @throws UnsupportedTermsException if the terms are null, blank or unrecognized
     * @throws TermsOutOfRangeException if the net days exceed 180
     */
    public static Date dueDate(Date invoiceDate, String terms) {
        return invoiceDate.addDays(parseNetDays(terms));
    }
}
