```apex
public with sharing class RecordSearchService {

    /** Maximum number of rows that a single search query may return. */
    private const Integer MAX_ROWS = 200;

    /**
     * Exception type used for every validation and security failure raised by
     * this service. Callers are expected to catch this type only.
     */
    public class SearchException extends Exception {
        public SearchException(String message) {
            super(message);
        }
    }

    /**
     * Runs one dynamic SOQL query that finds records of any object using simple
     * equality filters.
     *
     * <p>The query selects Id plus the requested fields from the object, applies
     * one `field = value` condition per filter (joined with AND), optionally
     * orders ascending by orderByField, and limits the result to maxRows.</p>
     *
     * <p>Object and field names are case-insensitive. Filter values are bound as
     * positional parameters, so the query is safe against SOQL injection. The
     * query executes in the running user's context (record sharing is honoured)
     * and every involved object/field is validated for field-level security
     * before the query runs.</p>
     *
     * @throws SearchException when validation or security fails
     */
    public static List<SObject> search(
            String objectApiName,
            List<String> fields,
            Map<String, Object> filters,
            String orderByField,
            Integer maxRows) {

        // ---- maxRows must be a non-null integer within 1..200 ----
        if (maxRows == null || maxRows < 1 || maxRows > MAX_ROWS) {
            throw new SearchException(
                'maxRows must be between 1 and ' + MAX_ROWS + ' but was ' + maxRows);
        }

        // ---- at least one field must be requested ----
        if (fields == null || fields.isEmpty()) {
            throw new SearchException('At least one field must be requested.');
        }

        // ---- the object must exist ----
        DescribeSObjectResult objectDesc = describeObject(objectApiName);

        // ---- the running user must be able to read/query the object ----
        if (!objectDesc.isReadable() || !objectDesc.isQueryable()) {
            throw new SearchException(
                'The running user cannot read the object: ' + objectApiName);
        }

        // Case-insensitive lookup of every field on the object.
        Map<String, DescribeSObjectResult.Field> fieldMap = buildFieldMap(objectDesc);

        // ---- build the SELECT field list (Id is always included) ----
        List<String> selectFields = new List<String>();
        selectFields.add('Id');
        for (String fieldName : fields) {
            DescribeSObjectResult.Field f = requireField(fieldMap, fieldName);
            requireReadable(f);
            requireQueryable(f);
            addDistinct(selectFields, f.getName());
        }

        // ---- build the WHERE clause and its bound values ----
        List<String> whereClauses = new List<String>();
        List<Object> bindValues = new List<Object>();
        if (filters != null && !filters.isEmpty()) {
            for (Map.Entry<String, Object> entry : filters.entrySet()) {
                DescribeSObjectResult.Field f = requireField(fieldMap, entry.getKey());
                requireReadable(f);
                if (!f.isFilterable()) {
                    throw new SearchException(
                        'The filter field is not filterable: ' + f.getName());
                }
                whereClauses.add(Schema.escapeQueryBraces(f.getName()) + ' = ?');
                bindValues.add(entry.getValue());
            }
        }

        // ---- build the optional ORDER BY clause ----
        DescribeSObjectResult.Field orderField = null;
        if (isNotBlank(orderByField)) {
            orderField = requireField(fieldMap, orderByField);
            requireReadable(orderField);
            if (!orderField.isSortable()) {
                throw new SearchException(
                    'The order-by field is not sortable: ' + orderField.getName());
            }
        }

        // ---- assemble and execute the single SOQL statement ----
        String soql = 'SELECT ' + String.join(selectFields, ', ') +
            ' FROM ' + Schema.escapeQueryBraces(objectApiName);
        if (!whereClauses.isEmpty()) {
            soql += ' WHERE ' + String.join(whereClauses, ' AND ');
        }
        if (orderField != null) {
            soql += ' ORDER BY ' + Schema.escapeQueryBraces(orderField.getName()) + ' ASC';
        }
        soql += ' LIMIT ' + maxRows;

        // Bind filter values as positional parameters -> injection safe.
        Database.QueryOptions options = new Database.QueryOptions();
        options.setBindVariables(bindValues);
        return Database.query(soql, options);
    }

    // ------------------------------------------------------------------
    // Helpers
    // ------------------------------------------------------------------

    private static DescribeSObjectResult describeObject(String objectApiName) {
        SObjectType sObjectType;
        try {
            sObjectType = Schema.getSObjectType(objectApiName);
        } catch (Exception e) {
            sObjectType = null;
        }
        if (sObjectType == null) {
            throw new SearchException('The object does not exist: ' + objectApiName);
        }
        try {
            return sObjectType.getDescribe();
        } catch (Exception e) {
            throw new SearchException('The object does not exist: ' + objectApiName);
        }
    }

    private static Map<String, DescribeSObjectResult.Field> buildFieldMap(
            DescribeSObjectResult objectDesc) {
        Map<String, DescribeSObjectResult.Field> fieldMap =
            new Map<String, DescribeSObjectResult.Field>();
        for (DescribeSObjectResult.Field f : objectDesc.getFields()) {
            fieldMap.put(f.getName().toLowerCase(), f);
        }
        return fieldMap;
    }

    private static DescribeSObjectResult.Field requireField(
            Map<String, DescribeSObjectResult.Field> fieldMap, String fieldName) {
        if (fieldName == null) {
            throw new SearchException('A field name cannot be null.');
        }
        DescribeSObjectResult.Field f = fieldMap.get(fieldName.toLowerCase());
        if (f == null) {
            throw new SearchException('"' + fieldName + '" is not a field of the object.');
        }
        return f;
    }

    private static void requireReadable(DescribeSObjectResult.Field f) {
        if (!f.isReadable()) {
            throw new SearchException(
                'The running user cannot read the field: ' + f.getName());
        }
    }

    private static void requireQueryable(DescribeSObjectResult.Field f) {
        if (!f.isQueryable()) {
            throw new SearchException(
                'The field is not queryable: ' + f.getName());
        }
    }

    private static void addDistinct(List<String> list, String value) {
        if (!list.contains(value)) {
            list.add(value);
        }
    }

    private static Boolean isNotBlank(String value) {
        return value != null && !value.trim().isEmpty();
    }
}
