public without sharing class AccountScoringJob implements System.Queueable {
    private static final Integer BATCH_SIZE = 200;
    private static final Decimal HOT_THRESHOLD = 1000000;
    private static final Decimal WARM_THRESHOLD = 100000;

    private final List<Id> accountIds;

    public AccountScoringJob(List<Id> accountIds) {
        this.accountIds = accountIds;
    }

    public void execute(System.QueueableContext context) {
        // Guard against a null/empty payload (e.g. execute(null) called directly).
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        // Process the first BATCH_SIZE ids; keep the rest for the next job in the chain.
        Integer endIndex = Math.min(accountIds.size(), BATCH_SIZE);
        List<Id> batchIds = new List<Id>();
        List<Id> remainingIds = new List<Id>();
        for (Integer i = 0; i < accountIds.size(); i++) {
            if (i < endIndex) {
                batchIds.add(accountIds[i]);
            } else {
                remainingIds.add(accountIds[i]);
            }
        }

        // Single SOQL query for this execution.
        List<Account> toUpdate = new List<Account>();
        for (Account acc : [
            SELECT Id, AnnualRevenue
            FROM Account
            WHERE Id IN :batchIds
        ]) {
            toUpdate.add(new Account(Id = acc.Id, Rating = getRating(acc.AnnualRevenue)));
        }

        // Single DML statement for this execution.
        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }

        // Chain the next job with the remaining ids (always chain, even in tests).
        if (!remainingIds.isEmpty()) {
            System.enqueueJob(new AccountScoringJob(remainingIds));
        }
    }

    private static String getRating(Decimal annualRevenue) {
        if (annualRevenue != null) {
            if (annualRevenue >= HOT_THRESHOLD) {
                return 'Hot';
            }
            if (annualRevenue >= WARM_THRESHOLD) {
                return 'Warm';
            }
        }
        return 'Cold';
    }

    public static Id start(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return null;
        }
        return System.enqueueJob(new AccountScoringJob(accountIds));
    }
}
