```apex
public class ErpSyncFinalizer implements Finalizer {
    private final Set<Id> accountIds;
    private final Integer attempt;

    public ErpSyncFinalizer(Set<Id> accountIds, Integer attempt) {
        this.accountIds = accountIds;
        this.attempt = attempt;
    }

    /**
     * Runs after the Queueable transaction completes. Records the outcome of the
     * run in FB_Job_Log__c and, on failure below the maximum attempt, retries.
     */
    public void execute(FinalizerContext context) {
        FB_Job_Log__c logEntry = new FB_Job_Log__c(
            Job_Name__c = 'ErpAccountSyncJob',
            Attempt__c = attempt
        );

        if (context.getIsSuccessful()) {
            logEntry.Status__c = 'Success';
        } else {
            logEntry.Status__c = 'Failed';

            String message = '';
            List<String> messages = context.getExceptionMessages();
            if (messages != null && !messages.isEmpty()) {
                message = messages[0];
            }
            // Error__c is Text(255); keep at most 255 characters.
            if (message.length() > 255) {
                message = message.substring(0, 255);
            }
            logEntry.Error__c = message;

            // Retry up to 3 total attempts; after the third failed attempt stop.
            if (attempt < 3) {
                System.enqueueJob(new ErpAccountSyncJob(accountIds, attempt + 1));
            }
        }

        // The finalizer runs in its own post-transaction context, so this insert
        // survives even when the original job rolled back all of its changes.
        insert logEntry;
    }
}
