            Id accId = (Id) ar.get('acc');
            Decimal pipeline = (Decimal) ar.get('openPipeline');
            pipelineByAccount.put(accId, pipeline == null ? 0 : pipeline);
            Integer count = (Integer) ar.get('openCount');
            countByAccount.put(accId, count == null ? 0 : count);
        }

        // Accounts with no open opportunities are absent from the aggregate, so
        // they default to 0 / 0 (never blank).
        List<Account> accountsToUpdate = new List<Account>();
        for (Id accId : accountIds) {
            accountsToUpdate.add(new Account(
                Id = accId,
                FB_Open_Pipeline__c = pipelineByAccount.containsKey(accId)
                    ? pipelineByAccount.get(accId)
                    : 0,
                FB_Open_Opportunities__c = countByAccount.containsKey(accId)
                    ? countByAccount.get(accId)
                    : 0
            ));
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
