```apex
public class ErpCustomerSync {

    private static final String ENDPOINT = 'callout:ERP/api/customers';

    /**
     * Entry point invoked by the Account after-insert trigger.
     *
     * One Queueable callout is enqueued per Account, so every new account is
     * pushed to the ERP as its own HTTP request (one request per account) and
     * can be traced individually on the ERP side.
     *
     * The callout is deliberately performed from an enqueued Queueable rather
     * than synchronously inside the trigger: the platform does not permit
     * callouts from triggers (that is exactly the "Callout from triggers are
     * currently not supported" failure we had to fix), and enqueuing a
     * Queueable per record is the recommended, bulk-safe pattern for making
     * callouts from a trigger.
     */
    public static void pushToErp(List<Account> accounts) {
        if (accounts == null) {
            return;
        }
        for (Account account : accounts) {
            System.enqueueJob(new ErpCustomerPush(account));
        }
    }

    private class ErpCustomerPush implements Queueable {
        private final Account account;

        public ErpCustomerPush(Account account) {
            this.account = account;
        }

        public void execute(QueueableContext context) {
            HttpRequest request = new HttpRequest();
            request.setEndpoint(ENDPOINT);
            request.setMethod('POST');
            request.setHeader('Content-Type', 'application/json');
            request.setBody(JSON.serialize(new List<ErpCustomer> { toCustomer() }));
            request.setTimeout(120000);

            // In tests this is intercepted by Test.setMock; in production it is
            // the real callout. The ERP returns 202 Accepted; error handling and
            // retries are out of scope for this ticket.
            HttpResponse response = new Http().send(request);

            System.debug(LoggingLevel.INFO,
                'Pushed account ' + account.Id + ' to ERP (status ' +
                response.getStatusCode() + ')');
        }

        private ErpCustomer toCustomer() {
            ErpCustomer customer = new ErpCustomer();
            customer.salesforceId = account.Id;      // 18-char Account Id
            customer.name = account.Name;
            customer.country = blankToNull(account.BillingCountry);
            return customer;
        }

        private String blankToNull(String value) {
            return String.isBlank(value) ? null : value;
        }
    }

    /** Single-customer payload. Field declaration order defines the JSON key order. */
    public class ErpCustomer {
        public String salesforceId;
        public String name;
        public String country;
    }
}
