```apex
public class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {

    /*
     * NPSP Table-Driven Trigger Management (TDTM) handler.
     *
     * Creates one high-priority "Major gift thank-you call" Task whenever an
     * Opportunity is inserted as, or is updated to become, Closed Won with
     * Amount >= 5000. Editing a gift that already qualified does not create a
     * second task.
     *
     * Register in NPSP Settings > Trigger Configuration with Trigger Action
     * "AfterInsert;AfterUpdate", Load Order 5, asynchronous disabled. The
     * handler runs only while its Trigger Handler record is active; unchecking
     * Active on that record stops it from firing.
     *
     * Bulk-safe: a single pass over the records, 0 SOQL queries and at most
     * 1 DML statement (one insert).
     */

    private static final String CLOSED_WON_STAGE = 'Closed Won';
    private static final Decimal MAJOR_GIFT_THRESHOLD = 5000;

    public override npsp.TDTM_Runnable.DmlWrapper run(
        List<SObject> newlist,
        List<SObject> oldlist,
        npsp.TDTM_Runnable.Action triggerAction,
        Schema.DescribeSObjectResult objResult
    ) {
        List<SObject> tasksToCreate = new List<SObject>();

        Boolean isInsert = (triggerAction == npsp.TDTM_Runnable.Action.AfterInsert);

        for (Integer i = 0; i < newlist.size(); i++) {
            Opportunity newOpp = (Opportunity) newlist[i];

            // Only act when the incoming record is Closed Won with a major Amount.
            if (!isMajorGiftClosedWon(newOpp)) {
                continue;
            }

            if (isInsert) {
                // No prior state on insert; a qualifying record always qualifies.
                tasksToCreate.add(buildFollowUpTask(newOpp));
            } else if (triggerAction == npsp.TDTM_Runnable.Action.AfterUpdate) {
                // Only fire when the record was NOT already a qualifying gift.
                Opportunity oldOpp = (oldlist != null && i < oldlist.size())
                    ? (Opportunity) oldlist[i]
                    : null;
                if (!isMajorGiftClosedWon(oldOpp)) {
                    tasksToCreate.add(buildFollowUpTask(newOpp));
                }
            }
        }

        // One DML statement total, and none when there is nothing to insert.
        if (tasksToCreate.isEmpty()) {
            return null;
        }

        // DmlOperation is an enum nested inside the DmlWrapper class.
        return new npsp.TDTM_Runnable.DmlWrapper(
            npsp.TDTM_Runnable.DmlWrapper.DmlOperation.INSERT,
            tasksToCreate
        );
    }

    private static Boolean isMajorGiftClosedWon(Opportunity opp) {
        return opp != null
            && opp.StageName == CLOSED_WON_STAGE
            && opp.Amount != null
            && opp.Amount >= MAJOR_GIFT_THRESHOLD;
    }

    private static Task buildFollowUpTask(Opportunity opp) {
        Task task = new Task();
        task.Subject = 'Major gift thank-you call';
        task.Priority = 'High';
        task.Status = 'Not Started';
        task.WhatId = opp.Id;
        task.WhoId = opp.npsp__Primary_Contact__c;
        task.OwnerId = opp.OwnerId;
        task.ActivityDate = opp.CloseDate != null ? opp.CloseDate.addDays(3) : null;
        return task;
    }
}
