public with sharing class EmployeeDirectoryService {

    /**
     * Returns the FB_Employee__c records the running user can see through
     * sharing rules (record-level sharing is NOT bypassed), ordered by Name
     * ascending.
     *
     * Field-level security is enforced: each sensitive custom field
     * (Department__c, Salary__c, Personal_Email__c) is only selected when the
     * running user can read it, so a field the user cannot read is absent from
     * the returned records rather than present with a null value. The method
     * never throws because of field-level security: a user who can read only
     * some of the fields still receives the records with the fields they can
     * read. If the running user cannot read FB_Employee__c at all, an empty
     * list is returned.
     *
     * @return List of FB_Employee__c containing only the fields the running
     *         user can read.
     */
    public static List<FB_Employee__c> getDirectory() {
        // Determine, per field, whether the running user can read it. SOQL
        // rejects a field the running user cannot read (field-level security is
        // validated when the query is compiled), so a probe that succeeds means
        // the field is readable and one that throws means it is not.
        Boolean canReadDepartment = isFieldReadable('Department__c');
        Boolean canReadSalary     = isFieldReadable('Salary__c');
        Boolean canReadEmail      = isFieldReadable('Personal_Email__c');

        // Build the SELECT clause from only the fields the user can read. Id and
        // Name are always included.
        String selectClause = 'Id, Name';
        if (canReadDepartment) selectClause += ', Department__c';
        if (canReadSalary)     selectClause += ', Salary__c';
        if (canReadEmail)      selectClause += ', Personal_Email__c';

        String soql = 'SELECT ' + selectClause
                      + ' FROM FB_Employee__c ORDER BY Name ASC';

        try {
            // The class is declared "with sharing", so this dynamic query still
            // honors the running user's record-level sharing settings. If the
            // running user cannot read the object at all, the query throws and
            // we return an empty list instead.
            return (List<FB_Employee__c>) Database.query(soql);
        } catch (Exception e) {
            return new List<FB_Employee__c>();
        }
    }

    /**
     * Returns true when a SOQL probe for the given field succeeds for the
     * running user. Because field-level security is enforced when a SOQL query
     * is compiled, selecting a field the running user cannot read throws, which
     * means the field is not readable.
     *
     * @param fieldName Api name of the FB_Employee__c field to test.
     */
    private static Boolean isFieldReadable(String fieldName) {
        String probe = 'SELECT ' + fieldName + ' FROM FB_Employee__c LIMIT 1';
        try {
            Database.query(probe);
            return true;
        } catch (Exception e) {
            return false;
        }
    }
}
